#!/usr/bin/env python3
"""PreToolUse guard: block hand-edits of generated files.

Reads the hook payload on stdin; when the Edit/Write target is a generated file,
emits a deny decision whose reason points at the command that regenerates it.
Silent (allow) otherwise.
"""

import json
import sys

GENERATED = {
    "conformance/vectors.json": (
        "conformance/vectors.json is generated from the Rust crate and CI diffs it "
        "byte-for-byte against the generator output. Regenerate it instead: "
        "cd keyless-rust && cargo run --example gen_conformance --features ss58 "
        "> ../conformance/vectors.json"
    ),
    "keyless-python/requirements-dev.txt": (
        "requirements-dev.txt is the hash-pinned lock compiled from requirements-dev.in; "
        "CI regenerates it and fails on drift. Edit requirements-dev.in and rerun the "
        "pip-compile command recorded in its header."
    ),
    "keyless-rust/Cargo.lock": (
        "Cargo.lock is regenerated by cargo (CI runs --locked and audits it). Change "
        "Cargo.toml and let a cargo command rewrite the lock; release versions go "
        "through .github/scripts/release_metadata.py --set."
    ),
    "keyless-rust/fuzz/Cargo.lock": (
        "fuzz/Cargo.lock is regenerated by cargo in the standalone fuzz workspace and "
        "audited by CI. Change fuzz/Cargo.toml and let cargo rewrite it; release "
        "versions go through .github/scripts/release_metadata.py --set."
    ),
    "keyless-ts/package-lock.json": (
        "package-lock.json is regenerated by npm (npm ci verifies it). Use npm "
        "install/update; release versions go through "
        ".github/scripts/release_metadata.py --set."
    ),
}


def main() -> None:
    try:
        payload = json.load(sys.stdin)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return
    file_path = (payload.get("tool_input") or {}).get("file_path") or ""
    normalized = file_path.replace("\\", "/")
    for suffix, reason in GENERATED.items():
        if normalized.endswith(suffix):
            print(
                json.dumps(
                    {
                        "hookSpecificOutput": {
                            "hookEventName": "PreToolUse",
                            "permissionDecision": "deny",
                            "permissionDecisionReason": reason,
                        }
                    }
                )
            )
            return


if __name__ == "__main__":
    main()
